CID = 'functions2'
ARGS, KW, SCOPE, MUT, LAMBDA, REC, ITER, GEN, DEC = "*args: any number of positional arguments", "**kwargs: any number of keyword arguments", "Scope: where a variable lives", "The mutable default argument trap", "lambda: tiny one-line functions", "Recursion: a function that calls itself", "Iterators", "Generators and yield", "Decorators"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 T(1, ARGS, 'def add(*nums):\n    return sum(nums)\n\nprint(add(), add(5), add(1, 2, 3))', "`*nums` collects any number of arguments into a tuple, even none. The sum of an empty tuple is 0."),
 W(1, ARGS, 'Write `largest(*nums)` that returns the biggest of any number of values, using `max()`. Print `largest(4, 19, 7)`.', '# def largest(*nums):\n', 'def largest(*nums):\n    return max(nums)\n\nprint(largest(4, 19, 7))', "Inside the function, `nums` is a tuple, so built-ins like `max()` work on it."),
 W(1, KW, 'Write `show(**info)` that prints each key and value as `key: value`. Call `show(name="Asha", city="Pune")`.', '# def show(**info):\n', 'def show(**info):\n    for key, value in info.items():\n        print(f"{key}: {value}")\n\nshow(name="Asha", city="Pune")', "`**info` collects the keyword arguments into a dictionary."),
 W(1, LAMBDA, 'Make a lambda called `gst` that adds 18% to a price, and print `gst(100)`.', '# gst = lambda ...\n', 'gst = lambda price: price * 1.18\nprint(gst(100))', "`lambda parameter: expression` is a tiny function that returns the expression."),
 W(1, LAMBDA, '`students = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]`. Sort them by marks, highest first, with `key=lambda`, and print the list of names.', 'students = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]\n', 'students = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]\nranked = sorted(students, key=lambda s: s[1], reverse=True)\nprint([s[0] for s in ranked])', "The lambda tells `sorted()` what to compare: item 1 of each tuple, the marks."),
 F(1, SCOPE, "This code should print `1`, but it crashes. Fix it with `global`.", 'count = 0\ndef increment():\n    count += 1\n\nincrement()\nprint(count)', 'count = 0\ndef increment():\n    global count\n    count += 1\n\nincrement()\nprint(count)', "Assigning to `count` inside the function makes it local, so Python cannot read the old value. `global count` says: use the outside one. (Returning the new value is often cleaner.)"),
 T(1, SCOPE, 'x = 100\ndef demo():\n    x = 50\n    return x\n\nprint(demo(), x)', "The `x` inside the function is a new local variable. The global `x` is not touched."),
 F(1, ARGS, "This code should print `68`, but it crashes. Fix the call.", 'def add(*numbers):\n    return sum(numbers)\n\nvalues = [11, 12, 45]\nprint(add(values))', 'def add(*numbers):\n    return sum(numbers)\n\nvalues = [11, 12, 45]\nprint(add(*values))', "Passing the list makes `numbers` a tuple holding one list. `*values` unpacks the list into separate arguments."),
 # ---------- Medium ----------
 W(2, REC, 'Write a recursive function `power(base, exp)` (for `exp` of 0 or more): anything to the power 0 is 1. Print `power(2, 10)`.', '# def power(base, exp):\n', 'def power(base, exp):\n    if exp == 0:\n        return 1\n    return base * power(base, exp - 1)\n\nprint(power(2, 10))', "The base case (`exp == 0`) stops the recursion. Every other call makes the problem one step smaller."),
 W(2, LAMBDA, '`nums = [3, -1, 8, -5, 2]`. Use `filter()` with a lambda to keep the negative numbers, and `map()` with a lambda to square every number. Print both lists.', 'nums = [3, -1, 8, -5, 2]\n', 'nums = [3, -1, 8, -5, 2]\nprint(list(filter(lambda x: x < 0, nums)))\nprint(list(map(lambda x: x * x, nums)))', "`filter()` keeps the items where the lambda is `True`. `map()` applies the lambda to every item. Wrap both in `list()` to see them."),
 T(2, ITER, 'it = iter([10, 20, 30])\nprint(next(it))\nfor x in it:\n    print(x)', "`next()` takes 10 from the iterator. The `for` loop then continues from where it left off."),
 W(2, GEN, 'Write a generator `evens(n)` that yields the even numbers from 2 up to `n`. Print `list(evens(10))`.', '# def evens(n):\n', 'def evens(n):\n    for i in range(2, n + 1, 2):\n        yield i\n\nprint(list(evens(10)))', "`yield` hands out one value at a time. `list()` collects them all."),
 F(2, MUT, "The second call should print `['milk']`, but it prints `['apple', 'milk']`. Fix it.", 'def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nprint(add_item("apple"))\nprint(add_item("milk"))', 'def add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nprint(add_item("apple"))\nprint(add_item("milk"))', "A default list is made only once and shared by every call. Use `None` as the default and make a fresh list inside."),
 W(2, KW, 'Write `order(item, qty=1, **notes)` that prints `2 x Pizza`, then each note as `- key: value`. Call `order("Pizza", 2, spicy=True, table=4)`.', '# def order(item, qty=1, **notes):\n', 'def order(item, qty=1, **notes):\n    print(f"{qty} x {item}")\n    for key, value in notes.items():\n        print(f"- {key}: {value}")\n\norder("Pizza", 2, spicy=True, table=4)', "Normal parameters are filled first. Every extra keyword argument lands in the `notes` dictionary."),
 T(2, GEN, 'def gen():\n    yield 1\n    yield 2\n\ng = gen()\nprint(next(g), next(g), list(g))', "Each `next()` runs to the next `yield`. After two values the generator is used up, so `list(g)` is empty."),
 W(2, LAMBDA, '`products = {"pen": 12, "ink": 45, "pad": 30}`. Use `max()` with `key=lambda` on `items()` to print the most expensive product and its price.', 'products = {"pen": 12, "ink": 45, "pad": 30}\n', 'products = {"pen": 12, "ink": 45, "pad": 30}\nname, price = max(products.items(), key=lambda item: item[1])\nprint(name, price)', "`items()` gives (name, price) pairs, and the lambda tells `max()` to compare the prices."),
 W(2, SCOPE, 'Write `make_counter()` that returns an inner function. Each call of the inner function adds 1 to a counter (use `nonlocal`) and returns it. Make one counter, call it 3 times, and print the 3 results on one line.', '# def make_counter():\n', 'def make_counter():\n    count = 0\n    def step():\n        nonlocal count\n        count += 1\n        return count\n    return step\n\ncounter = make_counter()\nprint(counter(), counter(), counter())', "`nonlocal` lets the inner function change a variable of the outer function. The counter remembers its value between calls."),
 F(2, REC, "`fact(5)` should be `120`, but this code prints `0`. Fix the base case.", 'def fact(n):\n    if n == 0:\n        return 0\n    return n * fact(n - 1)\n\nprint(fact(5))', 'def fact(n):\n    if n == 0:\n        return 1\n    return n * fact(n - 1)\n\nprint(fact(5))', "Every result is multiplied by the base case, so a base case of 0 makes everything 0. 0! is 1."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, DEC, 'Write a decorator `shout` that makes the text returned by a function upper case. Decorate `greet(name)`, which returns `f"hello {name}"`, and print `greet("asha")`.', '# def shout(func):\n', 'def shout(func):\n    def wrapper(*args, **kwargs):\n        return func(*args, **kwargs).upper()\n    return wrapper\n\n@shout\ndef greet(name):\n    return f"hello {name}"\n\nprint(greet("asha"))', "The decorator returns a wrapper that calls the original function and changes its result. `@shout` swaps `greet` for that wrapper."),
 W(3, REC, 'Write a recursive `flatten(items)` that turns nested lists into one flat list. Use `isinstance(x, list)` to spot an inner list. Print `flatten([1, [2, [3, 4]], 5])`.', '# def flatten(items):\n', 'def flatten(items):\n    flat = []\n    for x in items:\n        if isinstance(x, list):\n            flat += flatten(x)\n        else:\n            flat.append(x)\n    return flat\n\nprint(flatten([1, [2, [3, 4]], 5]))', "When an item is itself a list, the function calls itself on it. Plain items are added directly."),
 W(3, GEN, 'Write a generator `running_total(values)` that yields the total so far after each value. Print `list(running_total([5, 10, 20]))`.', '# def running_total(values):\n', 'def running_total(values):\n    total = 0\n    for v in values:\n        total += v\n        yield total\n\nprint(list(running_total([5, 10, 20])))', "The generator keeps `total` between yields, so each value builds on the last one."),
 T(3, DEC, 'def twice(func):\n    def wrapper():\n        func()\n        func()\n    return wrapper\n\n@twice\ndef hi():\n    print("hi")\n\nhi()', "`@twice` replaces `hi` with `wrapper`, which calls the original `hi` two times."),
 W(3, LAMBDA, '`words = ["cherry", "apple", "kiwi", "plum"]`. Sort them by their LAST letter, using `key=lambda`, and print the list.', 'words = ["cherry", "apple", "kiwi", "plum"]\n', 'words = ["cherry", "apple", "kiwi", "plum"]\nprint(sorted(words, key=lambda w: w[-1]))', "The lambda returns `w[-1]`, so `sorted()` compares the last letters: e, i, m, y."),
 W(3, ARGS, 'Write `report(title, *values, **opts)`. It prints the title, a colon, then the total of `values`, with `opts["unit"]` in front when given. So `report("Sales", 100, 250, unit="₹")` prints `Sales: ₹350` and `report("Units", 3, 4)` prints `Units: 7`.', '# def report(title, *values, **opts):\n', 'def report(title, *values, **opts):\n    unit = opts.get("unit", "")\n    print(f"{title}: {unit}{sum(values)}")\n\nreport("Sales", 100, 250, unit="₹")\nreport("Units", 3, 4)', "`*values` is a tuple of the numbers and `**opts` a dictionary of options. `get()` gives an empty unit when none was passed."),
 F(3, GEN, "This code should print `[1, 4, 9]`, but it crashes. Fix it so the function hands out every square.", 'def squares(n):\n    for i in range(1, n + 1):\n        return i * i\n\nprint(list(squares(3)))', 'def squares(n):\n    for i in range(1, n + 1):\n        yield i * i\n\nprint(list(squares(3)))', "`return` ends the function with one number, and `list()` cannot loop over a number. `yield` turns the function into a generator of all the squares."),
]
